-- MP-0049: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin if not exists(select 1 from public.entities where slug='government' and type='bloc') then raise exception 'MP-0049: missing party parent'; end if; if exists(select 1 from public.entities where slug='kdm' and (type <> 'party' or owner_id is not null or parent_id is distinct from (select id from public.entities where slug='government'))) then raise exception 'MP-0049: party identity conflict'; end if; end $$;

insert into public.entities (type,parent_id,slug,name,short_name,bloc,description,profile_checked_at,profile_sources) select 'party',parent.id,'kdm','Parti Kesejahteraan Demokratik Masyarakat','KDM','government','A separate Sabah-based party supporting the federal government. Its August 2026 withdrawal concerned the GRS-led Sabah state government; it is not listed here as a GRS component.','2026-11-10','[{"label": "Parliament · current KDM representative", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4207"}, {"label": "KDM · state-government withdrawal, August 2026", "url": "https://www.malaysiakini.com/news/782229"}, {"label": "Federal government composition · March 2026", "url": "https://theedgemalaysia.com/node/794820"}, {"label": "SPR · current registered party emblems", "url": "https://www.spr.gov.my/parti-parti-yang-berdaftar/"}]'::jsonb from public.entities parent where parent.slug='government' and parent.type='bloc' on conflict (slug) do nothing;

do $$ begin if not exists(select 1 from public.entities where slug='government' and type='bloc') then raise exception 'MP-0049: missing party parent'; end if; if exists(select 1 from public.entities where slug='warisan' and (type <> 'party' or owner_id is not null or parent_id is distinct from (select id from public.entities where slug='government'))) then raise exception 'MP-0049: party identity conflict'; end if; end $$;

insert into public.entities (type,parent_id,slug,name,short_name,bloc,description,profile_checked_at,profile_sources) select 'party',parent.id,'warisan','Parti Warisan','WARISAN','government','A Sabah-based party supporting the federal Unity Government. Its state-level opposition role is separate from federal alignment.','2026-11-10','[{"label": "WARISAN · federal-government support confirmed, August 2026", "url": "https://www.bernama.com/en/news.php?id=2589775"}, {"label": "SPR · current registered party emblems", "url": "https://www.spr.gov.my/parti-parti-yang-berdaftar/"}]'::jsonb from public.entities parent where parent.slug='government' and parent.type='bloc' on conflict (slug) do nothing;

do $$ begin if not exists(select 1 from public.entities where slug='gabungan-rakyat-sabah' and type='alliance') then raise exception 'MP-0049: missing party parent'; end if; if exists(select 1 from public.entities where slug='upko' and (type <> 'party' or owner_id is not null or parent_id is distinct from (select id from public.entities where slug='gabungan-rakyat-sabah'))) then raise exception 'MP-0049: party identity conflict'; end if; end $$;

insert into public.entities (type,parent_id,slug,name,short_name,bloc,description,profile_checked_at,profile_sources) select 'party',parent.id,'upko','United Progressive Kinabalu Organisation','UPKO','government','A component of Gabungan Rakyat Sabah (GRS), admitted on 18 June 2026.','2026-11-10','[{"label": "GRS · UPKO admission, June 2026", "url": "https://www.nst.com.my/amp/news/regional/2026/06/1466676/grs-accepts-upko-newest-component-party"}, {"label": "UPKO · current leadership", "url": "https://www.upko.org/amt.html"}, {"label": "SPR · current registered party emblems", "url": "https://www.spr.gov.my/parti-parti-yang-berdaftar/"}]'::jsonb from public.entities parent where parent.slug='gabungan-rakyat-sabah' and parent.type='alliance' on conflict (slug) do nothing;

do $$ begin
 if not exists(select 1 from public.entities where slug='kdm' and type='party') then raise exception 'MP-0049: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='upko' and type='party') then raise exception 'MP-0049: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='warisan' and type='party') then raise exception 'MP-0049: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('wetrom-bahanda','isnaraissah-munirah-majilis','madius-tangau') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0049: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('kota marudu','kota belud','tuaran') and slug not in ('wetrom-bahanda','isnaraissah-munirah-majilis','madius-tangau')) then raise exception 'MP-0049: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0049:%' and (m.source_type <> 'editorial' or e.slug not in ('wetrom-bahanda','isnaraissah-munirah-majilis','madius-tangau') or m.import_key not like 'MP-0049:' || e.slug || ':%')) then raise exception 'MP-0049: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'wetrom-bahanda','Wetrom Bahanda','government','Member of the Dewan Rakyat','Kota Marudu','Sabah','Wetrom Bahanda represents Kota Marudu, Sabah, in the Dewan Rakyat. Affiliated with KDM.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4207','/portraits/wetrom-bahanda.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P168.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4207"}, {"label": "KDM · current deputy president, 13 August 2026", "url": "https://www.thestar.com.my/news/nation/2026/08/13/sabahs-bahanda-brothers-eyeing-return-to-bn"}, {"label": "KDM · Sabah state-government withdrawal, 15 August 2026", "url": "https://www.malaysiakini.com/news/782229"}]'::jsonb from public.entities parent where parent.slug='kdm' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'isnaraissah-munirah-majilis','Isnaraissah Munirah Majilis','government','Member of the Dewan Rakyat','Kota Belud','Sabah','Isnaraissah Munirah Majilis represents Kota Belud, Sabah, in the Dewan Rakyat. Affiliated with WARISAN.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4208','/portraits/isnaraissah-munirah-majilis.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P169.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4208"}, {"label": "Representative · own constituency profile", "url": "https://munirahmajilis.my/profil"}]'::jsonb from public.entities parent where parent.slug='warisan' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'madius-tangau','Madius Tangau','government','Member of the Dewan Rakyat','Tuaran','Sabah','Madius Tangau represents Tuaran, Sabah, in the Dewan Rakyat. Affiliated with UPKO.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4209','/portraits/madius-tangau.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P170.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4209"}, {"label": "UPKO · Tuaran representative, 20 March 2026", "url": "https://www.freemalaysiatoday.com/category/nation/2026/03/20/help-fund-suit-over-continental-shelf-rights-mp-urges-sabah-reps"}, {"label": "GRS · UPKO admission, 18 June 2026", "url": "https://www.nst.com.my/amp/news/regional/2026/06/1466676/grs-accepts-upko-newest-component-party"}]'::jsonb from public.entities parent where parent.slug='upko' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('wetrom-bahanda','isnaraissah-munirah-majilis','madius-tangau') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0049: concurrent ownership or identity change'; end if; end $$;

commit;
